// tailwind-scale: a port of the Grit rule of the same name. It tests the regexes of
// tailwind-scale.patterns.json (generated by gen-tailwind-scale.mjs, and read by
// landing/lint/check.mjs too) on every string literal and template chunk. That covers each node the
// Grit rule matched (a string literal, a template chunk, a JSX attribute string, a string member
// name) and a few more, such as an enum member name. A module path, such as an import source, and
// a string literal type are not class strings, and the Grit rule skipped them too.
import { readFileSync } from 'node:fs';

const MESSAGE =
  "Arbitrary value in a Tailwind class. Use a scale step (18px -> 4.5), a theme token from app/theme.css (colors, radii, shadows and variables included: write the token's utility, never `[var(--x)]` or `(--x)`), or a stock utility. Only calc()/min()/max()/clamp()/env(), viewport units, grid-cols/grid-rows and transition lists may stay arbitrary. A viewport breakpoint is `phone:` or `desktop:` (app/globals.css), never an arbitrary `min-`/`max-` breakpoint.";

const patterns = JSON.parse(
  readFileSync(new URL('../tailwind-scale.patterns.json', import.meta.url), 'utf8'),
).map((p) => new RegExp(p));

// Parents whose string child is a module path or a type, not a value.
const NOT_A_VALUE = new Set([
  'ImportDeclaration',
  'ExportNamedDeclaration',
  'ExportAllDeclaration',
  'TSLiteralType',
  'TSExternalModuleReference',
  'TSModuleDeclaration',
  'TSImportType',
]);

export default {
  meta: {
    type: 'problem',
    docs: { description: 'Disallow an arbitrary value in a Tailwind class.' },
    schema: [],
  },
  create(context) {
    const check = (node, text) => {
      if (patterns.some((p) => p.test(text))) context.report({ node, message: MESSAGE });
    };
    return {
      Literal(node) {
        if (typeof node.value === 'string' && !NOT_A_VALUE.has(node.parent?.type))
          check(node, context.sourceCode.getText(node));
      },
      TemplateElement(node) {
        check(node, node.value.raw);
      },
    };
  },
};
